// Prepare a reasonable HRP. Use known valid HRPs to maximize success.
const char *hrp_choices[] = {"bc", "tb", "bcrt"};
size_t hrp_idx = (size_t)(*FUZZ_PARAM(unsigned int) % (sizeof(hrp_choices)/sizeof(hrp_choices[0])));
const char *hrp = hrp_choices[hrp_idx];

// Version must be 0..16 inclusive.
int ver = (int)(*FUZZ_PARAM(unsigned int) % 17);

// Witness program length must be 2..40 bytes.
size_t prog_len = (size_t)(*FUZZ_PARAM(unsigned int) % 39) + 2; // [2,40]

// Source random bytes for the witness program.
std::string prog_src = FUZZ_PARAM_STR();
if (prog_src.size() < prog_len) {
    // Not enough random data to satisfy the required program length -> constraint violation for this attempt.
    FUZZ_BAIL();
}
const uint8_t *prog = reinterpret_cast<const uint8_t *>(prog_src.data());

// Output buffer must be at least 73 + strlen(hrp) bytes (includes space for NUL).
size_t out_cap = 73 + strlen(hrp);
std::vector<char> out(out_cap, '\0');

// Call the target function.
int ok = segwit_addr_encode(out.data(), hrp, ver, prog, prog_len);

// Caller must only use output if ok==1; we do not assert success here since inputs may be invalid per algorithm rules.
(void)ok;

// Expected HRP: pick from common networks to improve decode success.
const char *hrp_choices[] = {"bc", "tb", "bcrt"};
size_t hrp_idx = (size_t)(*FUZZ_PARAM(unsigned int) % (sizeof(hrp_choices)/sizeof(hrp_choices[0])));
const char *hrp = hrp_choices[hrp_idx];

// Address string to decode.
std::string addr = FUZZ_PARAM_STR();
// Ensure it is NUL-terminated when passed as c_str().

// Prepare required output buffers.
int ver = -1;
uint8_t prog[40];
size_t prog_len = 0;

// Call the target function.
int ok = segwit_addr_decode(&ver, prog, &prog_len, hrp, addr.c_str());

// If decode succeeded, enforce documented invariants.
if (ok) {
    // Version must be within 0..16 inclusive and prog_len within 2..40 for SegWit usage.
    FUZZ_ASSERT(ver >= 0 && ver <= 16, "segwit_addr_decode: version out of range on success");
    FUZZ_ASSERT(prog_len >= 2 && prog_len <= 40, "segwit_addr_decode: program length out of range on success");
}

// On failure, outputs are unspecified; we do not consume them.
(void)ok;

// HRP to encode with. Keep in the typical lowercase set for Bech32.
const char *hrp_choices[] = {"bc", "tb", "bcrt", "lnbc"};
size_t hrp_idx = (size_t)(*FUZZ_PARAM(unsigned int) % (sizeof(hrp_choices)/sizeof(hrp_choices[0])));
const char *hrp = hrp_choices[hrp_idx];
size_t hrp_len = strlen(hrp);

// Generate 5-bit data values (each 0..31).
size_t data_len = (size_t)(*FUZZ_PARAM(unsigned int) % 64); // up to 63 5-bit values to keep outputs small
std::vector<uint8_t> data(data_len);
{
    std::string src = FUZZ_PARAM_STR();
    // Ensure sufficient source randomness.
    if (src.size() < data_len) { FUZZ_BAIL(); }
    for (size_t i = 0; i < data_len; ++i) { data[i] = static_cast<uint8_t>(src[i] & 0x1F); }
}

// Max output len: typical cap for Bech32-family strings is 90 for SegWit usage.
size_t max_output_len = (size_t)(*FUZZ_PARAM(unsigned int) % 90) + 1; // [1,90]

// Minimal required capacity per API: strlen(hrp) + data_len + 8 (includes separator and checksum and NUL).
size_t min_required = hrp_len + data_len + 8;
if (min_required > max_output_len) {
    // Caller must ensure provided capacity is sufficient relative to max_output_len; otherwise it's API misuse.
    FUZZ_BAIL();
}

// Allocate the output buffer to at least min_required, but not exceeding a small cap.
size_t out_cap = min_required;
std::vector<char> out(out_cap, '\0');

// Choose encoding variant: BECH32 or BECH32m.
bech32_encoding enc = ( (*FUZZ_PARAM(unsigned int) & 1) ? BECH32_ENCODING_BECH32 : BECH32_ENCODING_BECH32M );

int ok = bech32_encode(out.data(), hrp, data.data(), data_len, max_output_len, enc);
// Only use out if ok==1; here we simply discard.
(void)ok;

// Prepare an input string and constrain its length to be within max_input_len.
std::string input = FUZZ_PARAM_STR();
// Choose a max input length within typical limits (<=90 for SegWit usage).
size_t max_input_len = (size_t)(*FUZZ_PARAM(unsigned int) % 90) + 1; // [1,90]
if (input.size() == 0) { FUZZ_BAIL(); }
if (input.size() > max_input_len) {
    // Truncate input to respect the declared maximum length.
    input.resize(max_input_len);
}

// Enforce buffer sizing requirements relative to input length.
size_t inlen = input.size();
if (inlen < 8) { // Too small to ever satisfy data buffer requirement (need at least inlen-8 >= 0 and something to parse)
    FUZZ_BAIL();
}
size_t hrp_cap = (inlen >= 6) ? (inlen - 6) : 0; // must be at least this large to hold HRP
size_t data_cap = (inlen >= 8) ? (inlen - 8) : 0; // must be at least this large to hold data
if (hrp_cap == 0 || data_cap == 0) { FUZZ_BAIL(); }

std::vector<char> hrp(hrp_cap, '\0');
std::vector<uint8_t> data(data_cap, 0);
size_t data_len = 0;

bech32_encoding enc = bech32_decode(hrp.data(), data.data(), &data_len, input.c_str(), max_input_len);

// If success, encoding must not be NONE.
if (enc != BECH32_ENCODING_NONE) {
    FUZZ_ASSERT(data_len <= data_cap, "bech32_decode: data_len exceeds provided buffer");
}

// Choose inbits/outbits commonly used for Bech32 conversions, but allow both directions.
int inbits  = ((*FUZZ_PARAM(unsigned int) & 1) ? 8 : 5);
int outbits = ((*FUZZ_PARAM(unsigned int) & 1) ? 5 : 8);
int pad = (int)(*FUZZ_PARAM(unsigned int) & 1);

// Prepare input bytes; values must be within range representable by inbits.
size_t inlen = (size_t)(*FUZZ_PARAM(unsigned int) % 128); // keep small
std::string src = FUZZ_PARAM_STR();
if (src.size() < inlen) { FUZZ_BAIL(); }
std::vector<uint8_t> inbuf(inlen);
uint8_t in_mask = (uint8_t)((1u << inbits) - 1u);
for (size_t i = 0; i < inlen; ++i) { inbuf[i] = static_cast<uint8_t>(src[i]) & in_mask; }

// Compute a safe upper bound for output length: ceil(inlen*inbits/outbits) + 1 for possible padding.
size_t worst = (inlen == 0) ? (size_t)0 : ((inlen * (size_t)inbits + (size_t)outbits - 1) / (size_t)outbits);
if (pad) { worst += 1; }
if (worst == 0) { worst = 1; }
if (worst > 2048) { worst = 2048; }

std::vector<uint8_t> outbuf(worst, 0);
size_t outlen = 0; // per API, initialize appropriately (typically 0) and function increments it

int ok = bech32_convert_bits(outbuf.data(), &outlen, outbits, inbuf.data(), inlen, inbits, pad);

if (ok) {
    // Validate that produced values fit within outbits and do not exceed buffer.
    FUZZ_ASSERT(outlen <= worst, "bech32_convert_bits: wrote beyond capacity");
    uint8_t out_mask = (uint8_t)((1u << outbits) - 1u);
    for (size_t i = 0; i < outlen; ++i) {
        FUZZ_ASSERT((outbuf[i] & ~out_mask) == 0, "bech32_convert_bits: output value exceeds outbits range");
    }
}

(void)ok;

