import random
import string
from typing import List, Tuple

# This generator produces valid Bech32/Bech32m strings, focusing on SegWit addresses
# with HRPs bc, tb, and bcrt. It constructs a valid witness program, encodes it to
# 5-bit groups, computes the appropriate checksum per BIP-173/BIP-350, and returns
# the address as bytes. It also sometimes generates generic Bech32 payloads to
# exercise bech32_decode independent of SegWit constraints.

# Constants and utilities adapted to Bech32/Bech32m specifications
_BECH32_CHARSET = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"
_CHARSET_REV = {c: i for i, c in enumerate(_BECH32_CHARSET)}

# Polymod generator values
_GENERATOR = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3]


def _bech32_hrp_expand(hrp: str) -> List[int]:
    return [ord(x) >> 5 for x in hrp] + [0] + [ord(x) & 31 for x in hrp]


def _polymod(values: List[int]) -> int:
    chk = 1
    for v in values:
        top = chk >> 25
        chk = ((chk & 0x1ffffff) << 5) ^ v
        for i in range(5):
            if (top >> i) & 1:
                chk ^= _GENERATOR[i]
    return chk


def _bech32_create_checksum(hrp: str, data: List[int], bech32m: bool) -> List[int]:
    const = 0x2bc830a3 if bech32m else 1
    values = _bech32_hrp_expand(hrp) + data
    pm = _polymod(values + [0, 0, 0, 0, 0, 0]) ^ const
    return [(pm >> 5 * (5 - i)) & 31 for i in range(6)]


def _bech32_verify_checksum(hrp: str, data: List[int]) -> Tuple[bool, bool]:
    pm = _polymod(_bech32_hrp_expand(hrp) + data)
    if pm == 1:
        return True, False  # bech32
    if pm == 0x2bc830a3:
        return True, True   # bech32m
    return False, False


def _bech32_encode(hrp: str, data: List[int], bech32m: bool) -> str:
    checksum = _bech32_create_checksum(hrp, data, bech32m)
    combined = data + checksum
    return hrp + '1' + ''.join(_BECH32_CHARSET[d] for d in combined)


def _convert_bits(data: bytes, from_bits: int, to_bits: int, pad: bool) -> List[int]:
    acc = 0
    bits = 0
    ret: List[int] = []
    maxv = (1 << to_bits) - 1
    for b in data:
        if b < 0 or b >> from_bits:
            return []
        acc = (acc << from_bits) | b
        bits += from_bits
        while bits >= to_bits:
            bits -= to_bits
            ret.append((acc >> bits) & maxv)
    if pad:
        if bits:
            ret.append((acc << (to_bits - bits)) & maxv)
    else:
        if bits >= from_bits or ((acc << (to_bits - bits)) & maxv):
            return []
    return ret


def _rand_choice(rng: random.Random, seq):
    return seq[rng.randrange(0, len(seq))]


def _gen_segwit_address(rng: random.Random) -> str:
    # Choose HRP and version
    hrp = _rand_choice(rng, ["bc", "tb", "bcrt"])

    # Choose witness version with bias toward common versions 0 and 1
    if rng.random() < 0.6:
        ver = _rand_choice(rng, [0, 1])
    else:
        ver = rng.randrange(0, 17)

    # Program length: 2..40 (with typical 20 or 32 common)
    if ver == 0:
        # Favor 20 (P2WPKH) and 32 (P2WSH)
        prog_len = _rand_choice(rng, [20, 32, rng.randrange(2, 41)])
    else:
        prog_len = rng.randrange(2, 41)

    prog = bytes(rng.getrandbits(8) for _ in range(prog_len))

    # Data part: version (5-bit) + converted program (8->5 bits, no padding false per BIP-173: pad= True for encoding)
    # BIP-173 uses 5-bit groups, converting 8->5 with pad=True when encoding witness prog
    data = [ver] + _convert_bits(prog, 8, 5, True)

    # Determine encoding: v0 uses bech32; v1+ uses bech32m (BIP-350)
    bech32m = (ver != 0)

    # Encode
    return _bech32_encode(hrp, data, bech32m)


def _gen_generic_bech32(rng: random.Random) -> str:
    # Generate arbitrary Bech32/Bech32m payload not necessarily SegWit
    # HRP: lowercase alphanum+[-] allowed before separator. We'll choose letters 1..15 len.
    hrp_len = rng.randrange(1, 12)
    hrp_chars = string.ascii_lowercase + string.digits
    hrp = ''.join(rng.choice(hrp_chars) for _ in range(hrp_len))

    # Data length: ensure total length <= 90. Reserve hrp + 1 + data + 6 <= 90
    max_data = max(1, 90 - (len(hrp) + 1 + 6))
    data_len = rng.randrange(1, max_data + 1)
    data = [rng.randrange(0, 32) for _ in range(data_len)]

    bech32m = rng.random() < 0.5
    return _bech32_encode(hrp, data, bech32m)


def _maybe_truncate(rng: random.Random, s: str) -> str:
    # The bech32_decode fuzzer sometimes limits max_input_len. Simulate by optional truncation
    if rng.random() < 0.2 and len(s) > 1:
        max_len = rng.randrange(1, min(90, len(s)))
        return s[:max_len]
    return s


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose between generating a valid SegWit address (more likely) or a generic Bech32 string
    if rng.random() < 0.75:
        s = _gen_segwit_address(rng)
    else:
        s = _gen_generic_bech32(rng)

    s = _maybe_truncate(rng, s)

    # Ensure NUL-termination not required in buffer; fuzzing infra uses std::string
    # but we'll keep ASCII bytes and cap size
    b = s.encode('ascii', 'strict')
    if len(b) > 4096:
        b = b[:4096]
    return b
